package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type User struct {
	ID       int    `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
	Role     string `json:"role"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// searchUsers handles user search with flexible filtering
func searchUsers(w http.ResponseWriter, r *http.Request) {
	field := r.URL.Query().Get("field")
	value := r.URL.Query().Get("value")
	operator := r.URL.Query().Get("op")

	if field == "" || value == "" {
		http.Error(w, "field and value required", http.StatusBadRequest)
		return
	}

	// Basic field validation - only allow known columns
	allowedFields := map[string]bool{"username": true, "email": true, "role": true, "id": true}
	if !allowedFields[strings.ToLower(field)] {
		http.Error(w, "invalid field", http.StatusBadRequest)
		return
	}

	if operator == "" {
		operator = "="
	}

	// NOTE: operator is NOT validated - allows injection via op parameter
	// field is validated against allowlist above
	query := fmt.Sprintf("SELECT id, username, email, role FROM users WHERE %s %s '%s'", field, operator, value)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var users []User
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Username, &u.Email, &u.Role); err != nil {
			continue
		}
		users = append(users, u)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(users)
}

// updateProfile allows users to update their display name
func updateProfile(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		UserID      int    `json:"user_id"`
		DisplayName string `json:"display_name"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Parameterized query - safe
	_, err := db.Exec("UPDATE users SET display_name = $1 WHERE id = $2", req.DisplayName, req.UserID)
	if err != nil {
		http.Error(w, "update failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"updated"}`))
}

// healthCheck exposes version info
func healthCheck(w http.ResponseWriter, r *http.Request) {
	var version string
	db.QueryRow("SELECT version()").Scan(&version)
	w.Write([]byte(fmt.Sprintf(`{"status":"ok","db_version":"%s"}`, version)))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/api/users/profile", updateProfile)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
